package com.theone.series.tv;
import android.content.Context;import android.util.JsonReader;import android.util.JsonToken;
import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
final class MediaRepository {
 private final File cacheDir;private final String server,token;private JSONObject secondary;private volatile int lastSuccessful=2;
 MediaRepository(Context c)throws Exception{cacheDir=new File(c.getFilesDir(),"catalogs");cacheDir.mkdirs();try(InputStream in=c.getAssets().open("private_cinema.json")){JSONObject x=new JSONObject(read(in));server=x.getString("relay_url");token=x.getString("relay_token");}if(!server.startsWith("https://rubenvanaggelen.com/")||token.isEmpty())throw new IOException("Source unavailable");try(InputStream in=c.getAssets().open("private_xtream_secondary.json")){secondary=new JSONObject(read(in));}catch(Exception ignored){}}
 private static String enc(String s){try{return URLEncoder.encode(s,"UTF-8").replace("+","%20");}catch(Exception e){throw new IllegalArgumentException();}}
 private static String read(InputStream in)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>100*1024*1024)throw new IOException("Catalog exceeds limit");}return out.toString("UTF-8");}
 private String secondaryApi(String action)throws Exception{return secondary.getString("server")+"/player_api.php?username="+enc(secondary.getString("username"))+"&password="+enc(secondary.getString("password"))+"&action="+action;}
 private HttpURLConnection connection(String url,boolean second,int readTimeout)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(readTimeout);if(!second)c.setRequestProperty("X-Cinema-Token",token);return c;}
 private android.util.AtomicFile cacheFile(String type){return new android.util.AtomicFile(new File(cacheDir,"series-v1.bin"));}
 private List<CatalogEntry> cached(String type){try(InputStream in=cacheFile(type).openRead()){return CatalogCodec.read(in,type);}catch(Exception ignored){return Collections.emptyList();}}
 private void save(String type,List<CatalogEntry> entries){android.util.AtomicFile file=cacheFile(type);FileOutputStream out=null;try{out=file.startWrite();CatalogCodec.write(out,entries);file.finishWrite(out);}catch(Exception ignored){if(out!=null)file.failWrite(out);}}
 List<CatalogEntry> load(String type)throws Exception{List<CatalogEntry> result=new ArrayList<>();load(type,(entries,complete,successful)->{if(complete)result.addAll(entries);});return result;}
 void load(String type,ProgressiveCatalog.Listener listener)throws Exception{
  if(!type.equals("series"))throw new IOException("Series only");List<ProgressiveCatalog.Source> sources=new ArrayList<>();
  sources.add(preview->loadSource(server+"?action=catalog&type=series",false,preview));if(secondary!=null)sources.add(preview->loadSource(secondaryApi("get_series"),true,preview));
  ProgressiveCatalog.loadStreaming(sources,cached(type),(entries,complete,successful)->{lastSuccessful=successful;listener.update(entries,complete,successful);if(successful>0)save(type,entries);});
 }
 private List<CatalogEntry> loadSource(String url,boolean second,ProgressiveCatalog.Preview preview)throws Exception{HttpURLConnection c=connection(url,second,45000);List<CatalogEntry> list=new ArrayList<>();try{if(c.getResponseCode()!=200)throw new IOException("Catalog unavailable");try(JsonReader reader=new JsonReader(new InputStreamReader(c.getInputStream(),StandardCharsets.UTF_8))){reader.beginArray();while(reader.hasNext()){
  int id=0;String title="",poster="",category="",movieId="";long added=0;reader.beginObject();while(reader.hasNext()){String key=reader.nextName();if(reader.peek()==JsonToken.NULL){reader.nextNull();continue;}switch(key){case "series_id":id=(int)number(reader);break;case "name":title=reader.nextString();break;case "cover":case "stream_icon":String candidate=reader.nextString();if(poster.isEmpty()&&!candidate.equalsIgnoreCase("null"))poster=candidate;break;case "category_id":category=reader.nextString();break;case "tmdb":case "tmdb_id":String identifier=reader.nextString();if(movieId.isEmpty()&&validIdentifier(identifier))movieId=identifier;break;case "last_modified":case "added":added=Math.max(added,number(reader));break;default:reader.skipValue();}}reader.endObject();if(id<=0||id>=1000000000||title.isEmpty())continue;if(second){id+=1000000000;poster=PosterMetadata.resolve(poster,secondary.getString("server"));}list.add(new CatalogEntry(id,title,"mp4",poster,category,"series",added,movieId));if(list.size()==256)preview.accept(new ArrayList<>(list));}reader.endArray();}}finally{c.disconnect();}return list;}
 EpisodeCatalog.Result episodes(List<CatalogEntry> parents)throws Exception{List<CatalogEntry> all=new ArrayList<>();ExecutorService workers=Executors.newFixedThreadPool(3);List<Future<List<CatalogEntry>>> tasks=new ArrayList<>();try{for(CatalogEntry parent:parents)tasks.add(workers.submit(()->episodeSource(parent)));int success=0;for(Future<List<CatalogEntry>> task:tasks)try{all.addAll(task.get(50,TimeUnit.SECONDS));success++;}catch(Exception ignored){task.cancel(true);}if(success==0)throw new IOException("Episodes unavailable");return EpisodeCatalog.merge(all);}finally{workers.shutdownNow();}}
 private List<CatalogEntry> episodeSource(CatalogEntry parent)throws Exception{boolean second=parent.id>=1000000000;String url=second?secondaryApi("get_series_info")+"&series_id="+(parent.id-1000000000):server+"?action=episodes&id="+parent.id;HttpURLConnection c=connection(url,second,30000);try{if(c.getResponseCode()!=200)throw new IOException("Episodes unavailable");JSONObject data=new JSONObject(read(c.getInputStream()));return EpisodeCatalog.parse(data,parent,second?secondary.getString("server"):server,second);}finally{c.disconnect();}}
 List<String> posters(CatalogEntry entry)throws Exception{if(entry.isEpisode())return Collections.emptyList();boolean second=entry.id>=1000000000;if(second&&secondary!=null){HttpURLConnection c=connection(secondaryApi("get_series_info")+"&series_id="+(entry.id-1000000000),true,15000);try{if(c.getResponseCode()==200)return PosterMetadata.candidates(new JSONObject(read(c.getInputStream())),secondary.getString("server"));}finally{c.disconnect();}}return Collections.emptyList();}
 void clearPosterCache(){}
 private static boolean validIdentifier(String s){if(s.length()==0||s.length()>10||s.charAt(0)<'1'||s.charAt(0)>'9')return false;for(int i=1;i<s.length();i++)if(s.charAt(i)<'0'||s.charAt(i)>'9')return false;return true;}
 private static long number(JsonReader r)throws Exception{try{return Long.parseLong(r.nextString());}catch(NumberFormatException e){return 0;}}
 boolean partialSources(){return secondary!=null&&lastSuccessful<2;}
 Map<String,String> headersForUri(String uri){return uri.startsWith(server+"?")?Collections.singletonMap("X-Cinema-Token",token):Collections.emptyMap();}
 String stream(CatalogEntry e){if(!e.isEpisode())throw new IllegalArgumentException("Select an episode");if(e.id>=1000000000&&secondary!=null)try{return secondary.getString("server")+"/series/"+enc(secondary.getString("username"))+"/"+enc(secondary.getString("password"))+"/"+(e.id-1000000000)+"."+e.extension;}catch(Exception error){throw new IllegalStateException("Source unavailable");}return server+"?action=stream&id="+e.id+"&ext="+e.extension+"&type=series";}
}
